<script setup lang="ts">import{LayoutDashboard,MessageCircleMore,Webhook,Bot,CreditCard,Settings,Smartphone,HelpCircle,Bell,Search,Menu,X,LogOut}from"lucide-vue-next";const{t}=useAppPreferences();const route=useRoute();const mobileOpen=ref(false);const items=computed(()=>[{icon:LayoutDashboard,label:t("overview"),to:"/dashboard"},{icon:Smartphone,label:t("whatsapp"),to:"/dashboard/whatsapp"},{icon:MessageCircleMore,label:t("chats"),to:"/dashboard/chats"},{icon:Webhook,label:t("webhooks"),to:"/dashboard/webhooks"},{icon:Bot,label:t("ai"),to:"/dashboard/ai"},{icon:CreditCard,label:t("subscription"),to:"/dashboard/subscription"},{icon:Settings,label:t("settings"),to:"/dashboard/settings"}]);watch(()=>route.path,()=>mobileOpen.value=false);async function logout(){await $fetch('/api/auth/logout',{method:'POST'});await navigateTo('/login')}</script>
